cluster_builder = CompetitiveClusterBuilder(as_of_date=as_of_date)
clusters, cluster_coverage = cluster_builder.build_from_programs(programs)

if not quiet:
    print(f"✓ Built {len(clusters)} competitive clusters", file=sys.stderr)

