def opacity(count, max_c):
    if count == 0: return 0
    return min(0.10 + (count / max_c) * 0.82, 0.92)

def cell_bg(modality, op):
    if op == 0: return ''
    if modality == 'protein/enzyme therapy': r,g,b = 217,119,6
    elif modality == 'small molecule': r,g,b = 37,99,235
    else: r,g,b = 100,116,139
    return f'background:rgba({r},{g},{b},{op:.2f});'

