    d = json.load(f)

cells = d['cells']
lanes = d['lanes']
columns = d['columns']
summary = d['summary']
meta = d['metadata']

named_lanes = [l for l in lanes if l != 'Unknown Mechanism']
lane_meta = {
    'Insulin': {'target': 'INSR', 'mod': 'biologic'},
    'Biguanide': {'target': 'AMPK', 'mod': 'small'},
    'GLP-1 receptor agonist': {'target': 'GLP1R', 'mod': 'biologic'},
    'GLP-1/GCGR dual agonist': {'target': 'GLP1R', 'mod': 'biologic'},
    'Sulfonylurea': {'target': 'KCNJ11', 'mod': 'small'},
