    'Alpha-glucosidase inhibitor': {'target': 'GBA', 'mod': 'small'},
}

col_labels = {
    'phase1': 'Phase 1',
    'phase2': 'Phase 2',
    'phase3': 'Phase 3',
    'approved': 'Approved',
    'unknown': 'Stage Unknown',
}

grid = {}
for lane in lanes:
