    for col in columns:
        progs = row.get(col, [])
        mods = [p.get('modality', '') for p in progs]
        dominant = max(set(mods), key=mods.count) if mods else ''
        grid[lane][col] = {'count': len(progs), 'modality': dominant, 'programs': [(p['asset_name'], p['company_name']) for p in progs]}

named_max = max(grid[lane][col]['count'] for lane in named_lanes for col in columns)

def opacity(count, max_c):
    if count == 0: return 0
    return min(0.10 + (count / max_c) * 0.82, 0.92)

def cell_bg(modality, op):
    if op == 0: return ''
    if modality == 'protein/enzyme therapy': r,g,b = 217,119,6
    elif modality == 'small molecule': r,g,b = 37,99,235
    else: r,g,b = 100,116,139
    return f'background:rgba({r},{g},{b},{op:.2f});'

def tp_list(programs, total):
    out = []
    shown = programs[:7]
    for asset, co in shown:
        out.append(f'<li><span class="ta">{html_mod.escape(asset)}</span><span class="tc">{html_mod.escape(co)}</span></li>')
    if total > len(shown):
        out.append(f'<li class="tm">+{total-len(shown)} more</li>')
    return ''.join(out)

def named_row(lane):
