        cell = grid[lane][col]
        cnt = cell['count']
        op = opacity(cnt, named_max)
        bg = cell_bg(cell['modality'], op)
        if cell['modality'] == 'protein/enzyme therapy': bc = '#D97706'
        elif cell['modality'] == 'small molecule': bc = '#2563EB'
        else: bc = '#64748B'
        if cnt == 0:
            cells_html += '<td class="c0"><span class="dash">—</span></td>'
        else:
            bar_style = f'background:{bc};opacity:{min(op+0.15,1.0):.2f};'
            progs_html = tp_list(cell['programs'], cnt)
            cells_html += f'<td class="cf" style="{bg}"><span class="cnt">{cnt}</span><div class="dbar" style="{bar_style}"></div><div class="tt"><div class="tth">{html_mod.escape(lane)} · {col_labels[col]}</div><ul class="ttl">{progs_html}</ul></div></td>'
    return f'<tr class="nr"><td class="lc"><div class="ln">{html_mod.escape(lane)}</div><div class="lm"><code class="tg">{target}</code><span class="tag {mod_class}">{mod_label}</span><span class="total-ct">{lane_total}</span></div></td>{cells_html}</tr>'

unk = grid['Unknown Mechanism']
unk_max = max(unk[col]['count'] for col in columns)
def unk_row():
    cells_html = ''
    for col in columns:
        cnt = unk[col]['count']
        op = min(0.06 + (cnt/unk_max)*0.30, 0.36) if cnt > 0 else 0
        bg = f'background:rgba(100,116,139,{op:.2f});' if op > 0 else ''
        if cnt == 0:
            cells_html += '<td class="c0 uc"><span class="dash">—</span></td>'
        else:
            progs_html = tp_list(unk[col]['programs'], cnt)
