    return f'<tr class="ur"><td class="lc ulc"><div class="ln uln">Unknown Mechanism</div><div class="lm"><span class="unk-pct">222 programs · 66%</span></div></td>{cells_html}</tr>'

rows_html = '\n'.join(named_row(l) for l in named_lanes)
unk_html = unk_row()

