file.content:
.ln { font-size: 11.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text); line-height: 1.2; }
.uln { color: var(--text-3); }
.lm { display: flex; align-items: center; gap: 6px; margin-top: 4px; flex-wrap: wrap; }
code.tg { font-family: 'Courier New', monospace; font-size: 10px; color: var(--text-3); }
.tag { font-size: 9px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; padding: 1px 5px; border-radius: 3px; }
.tb { background: rgba(217,119,6,0.12); color: #92400E; }
.ts { background: rgba(37,99,235,0.10); color: #1D4ED8; }
.total-ct { font-family: 'Courier New', monospace; font-size: 10px; color: var(--text-3); margin-left: auto; }
.unk-pct { font-size: 10px; color: var(--text-3); font-style: italic; }
td.c0 { text-align: center; padding: 0; background: var(--ground); }
td.c0.uc { background: var(--unk-bg); }
.dash { color: #CDD3E2; font-size: 13px; font-family: 'Courier New', monospace; }
td.cf { text-align: center; padding: 0; cursor: default; transition: filter 0.10s; }
td.cf:hover { filter: brightness(0.88); }
td.cf.uc { border-top: 2px dashed #CDD3E2; }
.cnt { font-family: 'Courier New', monospace; font-size: 19px; font-weight: 700; color: rgba(19,25,38,0.85); display: block; padding: 14px 8px 10px; line-height: 1; }
.ucnt { font-size: 17px; color: rgba(100,116,139,0.80); }
.dbar { position: absolute; bottom: 0; left: 0; right: 0; height: 3px; }
.tt {
  display: none; position: absolute; z-index: 100; background: #1B2334;
  color: #E8ECF5; border-radius: 5px; box-shadow: 0 8px 24px rgba(0,0,0,0.25);
  width: 270px; padding: 10px 12px; top: calc(100% + 4px); left: 50%;
  transform: translateX(-50%); font-size: 11.5px; pointer-events: none;
}
td.cf:hover .tt { display: block; }
.tth { font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.12em; color: #8A95A8; font-weight: 700; margin-bottom: 7px; padding-bottom: 6px; border-bottom: 1px solid rgba(255,255,255,0.10); }
.ttl { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 5px; }
.ta { display: block; font-weight: 600; color: #E2E8F3; font-size: 11.5px; }
.tc { display: block; font-size: 10.5px; color: #8A95A8; }
.tm { color: #6B7580; font-style: italic; font-size: 10.5px; margin-top: 3px; }
.legend { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; font-size: 11px; color: var(--text-2); padding: 12px 0 0; border-top: 1px solid var(--line); margin-top: 6px; }
.leg-item { display: flex; align-items: center; gap: 7px; }
.leg-dot { width: 12px; height: 12px; border-radius: 2px; flex-shrink: 0; }
.leg-sm { background: rgba(37,99,235,0.65); }
.leg-bio { background: rgba(217,119,6,0.65); }
.leg-unk { background: rgba(100,116,139,0.40); }
.leg-divider { width: 1px; height: 16px; background: var(--line); }
.leg-note { font-size: 10.5px; color: var(--text-3); font-style: italic; }
.data-notes { margin-top: 18px; border: 1px solid #E8C56A; background: #FFFBEB; border-radius: 5px; padding: 10px 14px; font-size: 11.5px; color: #78350F; }
.data-notes strong { font-weight: 700; letter-spacing: 0.03em; }
.data-notes ul { margin: 5px 0 0; padding-left: 16px; }
.data-notes li { margin-bottom: 3px; }
footer { border-top: 1px solid var(--line); padding: 14px 40px; font-size: 10px; color: var(--text-3); display: flex; flex-wrap: wrap; gap: 6px 24px; align-items: center; }
.foot-sep { width: 1px; height: 12px; background: var(--line); }
.foot-gov { font-weight: 700; color: #D41A1A; letter-spacing: 0.04em; font-size: 9.5px; }
@media (prefers-reduced-motion: reduce) { td.cf { transition: none; } }
</style>

